// Selected official application controller; generated by prepare_partner_detail_window_ui.py.
namespace Zjcs.Official.PartnersUI
{
using Object = UnityEngine.Object;
using Zjcs.Official.ProfessionUI;
using Zjcs.Official.WorldUI;
using MultiLanguageText = Zjcs.Official.WorldUI.WorldMultiLanguageText;
using System.Collections.Generic;
using UnityEngine;

public class NpcDetailLiveController : MonoBehaviour
{
	private struct NpcLiveLoadedData
	{
		public int Id;

		public int LastUseFrame;

		public IProfessionAssetOperation<GameObject> Handle;

		public void Dispose()
		{
			if (Id > 0)
			{
				Id = -1;
				Handle.Dispose();
				Handle = null;
			}
		}
	}

	private const string kCommonNpcLivePath = "Appearance/NpcLive/NpcDetailLiveItem";

	[SerializeField]
	private Transform mSlot;

	[SerializeField]
	private MonoDictionary<int, int> mMaxCacheCountDict;

	private NpcDetailLiveItem mLiveItem;

	private List<NpcLiveLoadedData> mLoadedList = new List<NpcLiveLoadedData>();



    private IPartnerDetailLiveControllerServices services;
    public void Configure(IPartnerDetailLiveControllerServices value)
    { services = value ?? throw new System.ArgumentNullException(nameof(value)); }

	private void OnDisable()
	{
		TryDestroyLastNpcLive();
		TryReleaseAsset(0);
	}

	public void ShowNpc(int npcClassId)
	{
		if (!((Object)(object)mLiveItem != (Object)null) || mLiveItem.NpcId != npcClassId)
		{
			TryDestroyLastNpcLive();
			GameObject orLoadPrefab = GetOrLoadPrefab(npcClassId);
			if (!((Object)(object)orLoadPrefab == (Object)null))
			{
				mLiveItem = services.Instantiate(orLoadPrefab, mSlot);
				mLiveItem.ShowNpc(npcClassId);
				TryReleaseAsset(GetMaxCacheCount());
			}
		}
	}

	private void TryDestroyLastNpcLive()
	{
		if (!((Object)(object)mLiveItem == (Object)null))
		{
			Object.Destroy((Object)(object)((Component)mLiveItem).gameObject);
			mLiveItem = null;
		}
	}

	private GameObject GetOrLoadPrefab(int id)
	{
		for (int i = 0; i < mLoadedList.Count; i++)
		{
			NpcLiveLoadedData value = mLoadedList[i];
			if (value.Id == id)
			{
				value.LastUseFrame = Time.frameCount;
				mLoadedList[i] = value;
				return value.Handle.Result;
			}
		}
		IProfessionAssetOperation<GameObject> assetOperationHandle = services.LoadPrefab("Appearance/NpcLive/NpcDetailLiveItem" + $"_{id}");
		if ((Object)(object)assetOperationHandle.Result == (Object)null)
		{
			assetOperationHandle = services.LoadPrefab("Appearance/NpcLive/NpcDetailLiveItem");
		}
		if ((Object)(object)assetOperationHandle.Result == (Object)null)
		{
			Debug.LogError("NpcDetailLiveController.ShowNpc load fail！");
			return null;
		}
		mLoadedList.Add(new NpcLiveLoadedData
		{
			Id = id,
			Handle = assetOperationHandle,
			LastUseFrame = Time.frameCount
		});
		return assetOperationHandle.Result;
	}

	private void TryReleaseAsset(int maxCount)
	{
		mLoadedList.Sort((NpcLiveLoadedData a, NpcLiveLoadedData b) => b.LastUseFrame.CompareTo(a.LastUseFrame));
		for (int num = mLoadedList.Count - 1; num >= maxCount; num--)
		{
			mLoadedList[num].Dispose();
			mLoadedList.RemoveAt(num);
		}
	}

	private int GetMaxCacheCount()
	{
		return services.MaxCacheCount;
	}
}

}
